class Solution {
public:
    int areaOfMaxDiagonal(vector<vector<int>>& dimensions) {
        int bestDiag = -1;
        int bestArea = 0;
        for (const auto& d : dimensions) {
            int l = d[0];
            int w = d[1];
            int diag = l * l + w * w;
            int area = l * w;
            if (diag > bestDiag || (diag == bestDiag && area > bestArea)) {
                bestDiag = diag;
                bestArea = area;
            }
        }
        return bestArea;
    }
};
